def _read(self):
    """Read the file and store the detectors."""
    currentName = ""
    grids = {}
    bins = None
    # Common grid suffixes that represent coordinate systems
    gridSuffixes = {"E", "R", "Z", "X", "Y", "T", "PHI", "COORD", "FP"}
    with KeywordParser(self.filePath, ["DET"], ["\n", "];"]) as parser:
        for chunk in parser.yieldChunks():
            name, data = cleanDetChunk(chunk)
            if currentName and name[:len(currentName)] != currentName:
                self._processDet(currentName, bins, grids)
                bins = data
                grids = {}
                currentName = name
            elif bins is None:
                currentName = name
                bins = data
            else:
                suffix = name[len(currentName):]
                # Only treat as grid if suffix is a recognized grid identifier
                if suffix in gridSuffixes:
                    grids[suffix] = data
                else:
                    # Treat as new detector since suffix is not a recognized grid
                    self._processDet(currentName, bins, grids)
                    bins = data
                    grids = {}
                    currentName = name
        self._processDet(currentName, bins, grids)

